    const travel=Number(r.minimumTravel)===0?'0':r.allowExtensiveTravel?'extensive':String(r.minimumTravel),industry=r.disciplines.length===1?r.disciplines[0]:'all';
    return `<section class="quick-search-controls" aria-label="Change job search"><div class="quick-search-heading"><strong>Change your search</strong><a class="text-button" href="contracts.html">C2C / business projects ↗</a><button class="text-button" data-live-action="reset-search-rules">Reset search filters</button></div><div class="quick-filter-grid">${select('government','Government / contracts',r.sector==='private'?'private':r.sector==='government'?'government':'all',[['all','Include all sectors'],['private','Exclude government & contracts'],['government','Government & contracts only']])}${select('travel','Travel',travel,[['extensive','Nationwide / extensive + 100%'],['100','Explicitly 100% only'],['75','75% or more'],['50','50% or more'],['0','Any travel level']])}${select('industry','Technical work',industry,[['all','All supported technical work'],['fiber','Fiber / telecom / cabling'],['field','Field service / installation'],['network','Network infrastructure'],['data_center','Data centers'],['electronics','Electronics / communications']])}${select('arrangement','Work arrangement',r.arrangement,forBusiness?[['all','C2C / 1099 / project bids'],['c2c','C2C explicitly offered'],['1099','1099 explicitly offered'],['project','Client project bids']]:[['all','All employee arrangements'],['w2','W-2 explicitly offered'],['contract','Contract assignments']])}${select('clearance','Clearance',r.clearance,[['exclude_active','Exclude active clearance'],['all','Any supported clearance'],['none','Explicitly no clearance'],['required','Active clearance required']])}<label>Minimum hourly USD<input id="quick-hourly" type="number" min="0" value="${r.minimumHourly||0}"></label></div><div class="quick-search-toggles"><label><input id="quick-faa" type="checkbox" ${r.excludeFAA?'checked':''}>Exclude jobs mentioning FAA</label><label><input id="quick-software" type="checkbox" ${r.remoteSoftware?'checked':''}>Include relevant remote software</label><button class="text-button" data-live-view="blocked_companies">Manage hidden companies</button></div><details class="quick-sources" ${sourceChoicesOpen?'open':''}><summary>Sources · ${E.sources().filter(E.sourceEnabled).length} enabled — turn any on or off</summary><div>${E.sources().filter(s=>!['manual','credential'].includes(s.kind)).map(s=>`<label><input type="checkbox" data-source-toggle="${esc(s.id)}" ${E.sourceEnabled(s)?'checked':''}>${esc(s.name)}</label>`).join('')}</div></details><small>Changes apply immediately to cached matches and future pulls. Your hidden companies and jobs are kept until you restore them.</small></section>`;
