    if(!d.profile.name){alert.innerHTML=`<div>${icon('user')}<div><strong>Make Jobbies work for you.</strong><p>Import your local profile and resumes to prepare applications and rank matches.</p></div></div><button class="primary-button" data-live-action="import-profile">Import my profile ${icon('arrow')}</button><button class="secondary-button" data-live-action="edit-profile">Set up manually</button>`;}
    if(tab==='blocked_companies'){renderBlockedCompanies();return;}if(tab==='review'){renderReviewQueue();return;}if(tab==='intelligence'){dom('#workbench').innerHTML=AmericaCompanion.panel();return;}if(tab==='sources'){renderSources();return;}if(tab==='wizard'){renderWizard();return;}if(tab==='answers'){renderAnswers();return;}if(tab==='profile'){renderProfile();return;}if(tab==='blocked_companies'){renderBlockedCompanies();return;}if(tab==='business'){renderBusiness();return;}if(tab==='search_rules'){renderSearchRules(false);return;}
    let list=filtered();if(tab==='opportunities'&&sortBy==='overall'){const travel=list.filter(j=>(j.travel100||j.travelExtensive)&&!j.softwareRole),other=list.filter(j=>!travel.includes(j));list=[...spreadEmployers(travel),...spreadEmployers(other)];}const slice=list.slice(0,page*limit);
    const queueStats=tab==='review'?`<div class="queue-stats"><span><b>${drafts.filter(a=>a.stage==='ready_for_review').length}</b> Ready for review</span><span><b>${drafts.filter(a=>a.stage==='needs_input').length}</b> Need your answers</span><span><b>${drafts.filter(a=>a.stage==='approved_for_handoff').length}</b> Approved to apply</span></div>`:'';
